processor-info.script:


String cmd = input.getText("cmd");

if("create".equals(cmd))
{
	String paper_id = input.getText("paper_id");

	String mode = "update";

	if ("0".equals(paper_id) || "".equals(paper_id)) {
		java.util.UUID uuid = java.util.UUID.randomUUID();
		long l = java.nio.ByteBuffer.wrap(uuid.toString().getBytes()).getLong();
		paper_id = Long.toString(l, Character.MAX_RADIX);
		input.put("paper_id", paper_id);

		mode = "insert";
	}

	if ("insert".equals(mode)) {
		executeSQL("insertPaper", connection, input, output);
	} else {
		executeSQL("updatePaper", connection, input, output);

		executeSQL("deletetQstnExmp", connection, input, output);
		executeSQL("deleteQstn", connection, input, output);				
	}

	String qstn_no = null;
	String exmp_seq_no = null;

	DataSet exmpInput = new DataSet();
	int jdx = 0;
	for (int idx=0; idx<input.getInt("qstn_cnt"); idx++) {
		qstn_no = paper_id + "_" + input.getText("qstn_id", idx);

		DataSet questionInput = new DataSet();
		questionInput.put("qstn_no", qstn_no);
		questionInput.put("paper_id", input.getText("paper_id"));
		questionInput.put("qstn_answ", input.getText("qstn_answ", idx));
		questionInput.put("answ_type", input.getText("answ_type", idx));				
		questionInput.put("answ_cnt", input.getText("answ_cnt", idx));
		questionInput.put("exmp_add_seq", input.getText("exmp_add_seq", idx));
		questionInput.put("multi_yn", input.getText("multi_yn", idx));
		questionInput.put("multi_cnt", input.getText("multi_cnt", idx));
		questionInput.put("connect_yn", input.getText("connect_yn", idx));
		questionInput.put("qstn_ord", input.getText("qstn_ord", idx));

		executeSQL("insertQstn", connection, questionInput, output);

		DataSet temp = (DataSet)input.get("qstn_"+idx);

		for (int kdx=0; kdx<temp.getMaxDataSize(); kdx++) {
			exmpInput.put("exmp_seq_no", qstn_no + "_" + temp.getText("exmp_id", kdx), jdx);
			exmpInput.put("qstn_no", qstn_no, jdx);
			exmpInput.put("exmp_sort_no", kdx+1, jdx);
			exmpInput.put("exmp_word", temp.getText("exmp_word", kdx), jdx);
			exmpInput.put("connect_qstn_no", paper_id+"_"+temp.getText("connect_qstn_no", kdx), jdx);
			jdx++;
		}
	}

	if (exmpInput.getMaxDataSize() > 0) {
		executeSQL("insertQstnExmp", connection, exmpInput, output);
	}

	output.put("paper_id", paper_id);
} else if ("drop".equals(cmd)) {
	executeSQL("deletePaper", connection, input, output);
	if(Integer.parseInt(output.getProperty("rowcount.update:deletePaper")) > 0){
		executeSQL("deletetQstnExmp", connection, input, output);
		executeSQL("deleteQstn", connection, input, output);
	}
} 
else if("answCreate".equals(cmd)){

	DataSet surveyAnswer = (DataSet)input.get("surveyAnswer");

	if(surveyAnswer.getMaxDataSize() > 1)
	{
		executeSQL("insertSurveyAnswPop", connection, surveyAnswer, output);
		executeSQL("updateCustProPop", connection, input, output);
	}	

}else if("answDeleteCreate".equals(cmd)){ 

	DataSet surveyAnswer = (DataSet)input.get("surveyAnswer");

	if(!"".equals(input.getText("user_lecture_seq_no"))){	
		executeSQL("deleteSurveyCust", connection, input, output);
		executeSQL("insertSurveyCust", connection, surveyAnswer, output);

		if(surveyAnswer.getMaxDataSize() > 0)
		{	
			executeSQL("deleteSurveyAnsw", connection, input, output);
			executeSQL("insertSurveyAnsw", connection, surveyAnswer, output);
		}	
	}		

}else
{
	executeSQL(cmd, connection, input, output);
}
